// Careers page: lists open jobs from Supabase and takes applications.
// Settings come from config.js (generated by build.py).
(function () {
  var cfg = window.FM_CONFIG || {};
  var listEl = document.getElementById('jobs-list');
  if (!listEl) return;

  var db = (cfg.supabaseUrl && cfg.supabaseKey && window.supabase)
    ? window.supabase.createClient(cfg.supabaseUrl, cfg.supabaseKey, { auth: { persistSession: false } })
    : null;

  var jobId = new URLSearchParams(location.search).get('job');

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  // Plain text to HTML: blank line = new paragraph, lines starting "- " or "* " = bullets,
  // a short line ending in ":" = a small heading.
  function formatText(text) {
    var out = [];
    String(text || '').replace(/\r/g, '').split(/\n\s*\n/).forEach(function (block) {
      var lines = block.split('\n').map(function (l) { return l.trim(); }).filter(Boolean);
      var bullets = [];
      var flush = function () {
        if (bullets.length) out.push('<ul class="includes job-list-bullets">' + bullets.join('') + '</ul>');
        bullets = [];
      };
      var para = [];
      var flushPara = function () {
        if (para.length) out.push('<p>' + para.join('<br>') + '</p>');
        para = [];
      };
      lines.forEach(function (line) {
        var m = line.match(/^[-*•]\s+(.*)$/);
        if (m) { flushPara(); bullets.push('<li>' + esc(m[1]) + '</li>'); return; }
        flush();
        if (line.length <= 60 && /:$/.test(line)) { flushPara(); out.push('<h3 class="list-title">' + esc(line.slice(0, -1)) + '</h3>'); return; }
        para.push(esc(line));
      });
      flush();
      flushPara();
    });
    return out.join('\n');
  }

  function fmtDate(d) {
    if (!d) return '';
    var dt = new Date(d + 'T00:00:00');
    return dt.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
  }

  function metaItems(job) {
    var items = [];
    if (job.location) items.push(['Location', job.location]);
    if (job.employment_type) items.push(['Type', job.employment_type]);
    if (job.salary) items.push(['Salary', job.salary]);
    if (job.closing_date) items.push(['Closes', fmtDate(job.closing_date)]);
    return items.map(function (i) {
      return '<li><span>' + esc(i[0]) + '</span>' + esc(i[1]) + '</li>';
    }).join('');
  }

  function emptyList() {
    listEl.innerHTML = '<p class="jobs-empty">There are no openings listed right now. Please check back soon.</p>';
  }

  // ------------------------------------------------------------ list
  function showList() {
    if (!db) { emptyList(); return; }
    db.from('jobs')
      .select('id,title,company,location,employment_type,salary,closing_date,summary')
      .order('created_at', { ascending: false })
      .then(function (res) {
        if (res.error) throw res.error;
        if (!res.data.length) { emptyList(); return; }
        listEl.innerHTML = res.data.map(function (job) {
          var href = 'careers.html?job=' + encodeURIComponent(job.id);
          return '<article class="job-card">' +
            '<div class="job-card-main">' +
              (job.company ? '<p class="eyebrow">' + esc(job.company) + '</p>' : '') +
              '<h3><a href="' + href + '">' + esc(job.title) + '</a></h3>' +
              '<ul class="job-meta">' + metaItems(job) + '</ul>' +
              (job.summary ? '<p>' + esc(job.summary) + '</p>' : '') +
            '</div>' +
            '<a class="btn btn-gold btn-sm" href="' + href + '">View &amp; Apply <span aria-hidden="true">&rarr;</span></a>' +
          '</article>';
        }).join('');
      })
      .catch(function () {
        listEl.innerHTML = '<p class="jobs-empty">We could not load the openings just now. Please refresh the page or try again later.</p>';
      });
  }

  // ------------------------------------------------------------ one job
  var currentJob = null;

  function notFound() {
    document.getElementById('jobs-view').hidden = false;
    listEl.innerHTML = '<p class="jobs-empty">That role is no longer open. <a class="text-link" href="careers.html">See current openings</a></p>';
  }

  function showJob() {
    if (!db) { notFound(); return; }
    document.getElementById('jobs-view').hidden = true;
    db.from('jobs').select('*').eq('id', jobId).maybeSingle()
      .then(function (res) {
        if (res.error || !res.data) { notFound(); return; }
        var job = currentJob = res.data;
        document.title = job.title + ' | Careers | Fynn-Micheals HR Solutions';
        document.getElementById('careers-title').textContent = job.title;
        document.getElementById('careers-sub').textContent =
          [job.employment_type, job.location].filter(Boolean).join(' · ') || 'Apply online below.';
        var crumb = document.getElementById('crumb-current');
        crumb.innerHTML = '<a href="careers.html">Careers</a> / ' + esc(job.title);
        document.getElementById('job-company').textContent = job.company || 'Job opening';
        document.getElementById('job-title').textContent = job.title;
        document.getElementById('job-meta').innerHTML = metaItems(job);
        document.getElementById('job-body').innerHTML =
          formatText(job.description || job.summary || '');
        document.getElementById('job-view').hidden = false;
      })
      .catch(notFound);
  }

  // ------------------------------------------------------------ apply
  var form = document.getElementById('apply-form');
  var note = document.getElementById('apply-note');
  var MAX = 5 * 1024 * 1024;
  var OK_TYPES = /\.(pdf|docx?)$/i;

  function uuid() {
    if (window.crypto && crypto.randomUUID) return crypto.randomUUID();
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
      var r = Math.random() * 16 | 0;
      return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
    });
  }

  function setInvalid(id, bad) {
    document.getElementById(id).closest('.field').classList.toggle('invalid', bad);
    return !bad;
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    if (!currentJob || !db) return;
    note.classList.remove('ok');

    var val = function (id) { return document.getElementById(id).value.trim(); };
    var file = document.getElementById('a-cv').files[0];
    var ok = [
      setInvalid('a-name', !val('a-name')),
      setInvalid('a-email', !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(val('a-email'))),
      setInvalid('a-phone', !val('a-phone')),
      setInvalid('a-cv', !file || !OK_TYPES.test(file.name) || file.size > MAX),
      setInvalid('a-consent', !document.getElementById('a-consent').checked)
    ].every(Boolean);
    if (!ok) {
      note.textContent = file && file.size > MAX
        ? 'Your CV is larger than 5 MB. Please upload a smaller file.'
        : 'Please check the highlighted fields.';
      return;
    }
    if (form.querySelector('[name="_honey"]').value) return; // bot

    var button = form.querySelector('button[type="submit"]');
    button.disabled = true;
    note.textContent = 'Uploading your CV…';

    var safeName = file.name.replace(/[^A-Za-z0-9._-]+/g, '_').slice(-120);
    var path = uuid() + '/' + safeName;
    var app = {
      job_id: currentJob.id,
      full_name: val('a-name'),
      email: val('a-email'),
      phone: val('a-phone'),
      location: val('a-location') || null,
      linkedin: val('a-linkedin') || null,
      cover_note: val('a-note') || null,
      cv_path: path
    };

    db.storage.from('cvs').upload(path, file, { contentType: file.type || undefined, upsert: false })
      .then(function (res) {
        if (res.error) throw res.error;
        note.textContent = 'Sending your application…';
        return db.from('applications').insert(app);
      })
      .then(function (res) {
        if (res.error) throw res.error;
        notifyOwner(app);
        form.innerHTML =
          '<div class="form-head full apply-done">' +
            '<h2>Application received</h2>' +
            '<p>Thank you, ' + esc(app.full_name) + '. Your application for <strong>' + esc(currentJob.title) +
            '</strong> has been sent. If your profile matches the role, we will contact you by email or phone.</p>' +
            '<p><a class="text-link" href="careers.html">See other openings</a></p>' +
          '</div>';
      })
      .catch(function () {
        note.textContent = 'Sorry, your application could not be sent. Please try again, or email your CV to ' +
          form.getAttribute('data-email') + '.';
        button.disabled = false;
      });
  });

  // Email the owner a heads-up through FormSubmit (the same service as the contact form).
  // The application is already saved, so a failure here is ignored.
  function notifyOwner(app) {
    var endpoint = form.getAttribute('data-endpoint');
    if (!endpoint || !window.fetch) return;
    var adminUrl = (cfg.siteUrl || location.origin) + '/admin.html';
    fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify({
        _subject: 'New application: ' + currentJob.title + ' - ' + app.full_name,
        _template: 'table',
        _captcha: 'false',
        _replyto: app.email,
        Role: currentJob.title,
        Name: app.full_name,
        Email: app.email,
        Phone: app.phone,
        Location: app.location || '-',
        LinkedIn: app.linkedin || '-',
        Note: app.cover_note || '-',
        'CV and full application': adminUrl
      })
    }).catch(function () {});
  }

  if (jobId) showJob(); else showList();
})();
